import pytest


def test_dynamic_xfail_failure_is_xfailed(testdir):
    testdir.makepyfile(
        """
        import pytest

        def test_f(request):
            request.node.add_marker(pytest.mark.xfail(reason="dyn"))
            assert 0
        """
    )
    result = testdir.runpytest("-rx")
    result.stdout.fnmatch_lines(["*XFAIL*test_f*", "*dyn*", "*1 xfailed*"])


def test_dynamic_xfail_pass_is_xpassed(testdir):
    testdir.makepyfile(
        """
        import pytest

        def test_p(request):
            request.node.add_marker(pytest.mark.xfail(reason="dyn"))
        """
    )
    result = testdir.runpytest("-rx")
    result.stdout.fnmatch_lines(["*XPASS*test_p*", "*1 xpassed*"])


def test_dynamic_xfail_strict_pass_fails(testdir):
    testdir.makepyfile(
        """
        import pytest

        def test_s(request):
            request.node.add_marker(pytest.mark.xfail(strict=True, reason="dyn"))
        """
    )
    result = testdir.runpytest()
    result.stdout.fnmatch_lines(["*XPASS(strict)*", "*1 failed*"])


def test_dynamic_xfail_raises_mismatch_fails(testdir):
    testdir.makepyfile(
        """
        import pytest

        def test_r(request):
            request.node.add_marker(pytest.mark.xfail(raises=ValueError, reason="dyn"))
            raise TypeError("boom")
        """
    )
    result = testdir.runpytest()
    result.stdout.fnmatch_lines(["*TypeError*", "*1 failed*"])


def test_dynamic_xfail_from_fixture(testdir):
    testdir.makepyfile(
        """
        import pytest

        @pytest.fixture
        def dyn(request):
            request.node.add_marker(pytest.mark.xfail(reason="dyn-fixture"))

        def test_f(dyn):
            assert 0
        """
    )
    result = testdir.runpytest("-rx")
    result.stdout.fnmatch_lines(["*1 xfailed*"])


def test_dynamic_xfail_run_false_from_fixture(testdir):
    testdir.makepyfile(
        """
        import pytest

        @pytest.fixture
        def dyn(request):
            request.node.add_marker(pytest.mark.xfail(run=False, reason="dyn-notrun"))

        def test_f(dyn):
            assert 0
        """
    )
    result = testdir.runpytest("-rx")
    result.stdout.fnmatch_lines(["*1 skipped*"])


def test_static_xfail_still_works(testdir):
    testdir.makepyfile(
        """
        import pytest

        @pytest.mark.xfail(reason="static")
        def test_f():
            assert 0
        """
    )
    result = testdir.runpytest("-rx")
    result.stdout.fnmatch_lines(["*1 xfailed*"])


def test_static_xfail_with_runxfail_fails(testdir):
    testdir.makepyfile(
        """
        import pytest

        @pytest.mark.xfail(reason="static")
        def test_f():
            assert 0
        """
    )
    result = testdir.runpytest("--runxfail")
    result.stdout.fnmatch_lines(["*1 failed*"])
